import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import {
  Container,
  Typography,
  Box,
  Grid,
  TextField,
  Button,
  Paper,
  Stepper,
  Step,
  StepLabel,
  Divider,
  Alert,
  Card,
  CardContent,
  InputAdornment,
  IconButton
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { useTheme } from '@mui/material/styles';
import { clearCart } from '../features/cartSlice';
import { selectCartItems, selectCartTotal } from '../features/cartSlice';
import { selectIsAuthenticated } from '../features/authSlice';
import {
  CreditCard as CreditCardIcon,
  LocationOn as LocationIcon,
  Payment as PaymentIcon,
  Visibility as VisibilityIcon,
  VisibilityOff as VisibilityOffIcon
} from '@mui/icons-material';

const CheckoutPage = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const isAuthenticated = useSelector(selectIsAuthenticated);
  const cartItems = useSelector(selectCartItems);
  const total = useSelector(selectCartTotal);
  const [activeStep, setActiveStep] = useState(0);
  const [showCvv, setShowCvv] = useState(false);
  const [showLoginAlert, setShowLoginAlert] = useState(false);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    address: '',
    city: '',
    country: '',
    zipCode: '',
    cardNumber: '',
    cardName: '',
    expiryDate: '',
    cvv: ''
  });
  const [errors, setErrors] = useState({});
  const [orderSuccess, setOrderSuccess] = useState(false);

  const steps = ['Shipping Information', 'Payment Details', 'Review Order'];

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleNext = () => {
    if (activeStep === steps.length - 1) {
      handlePlaceOrder();
    } else {
      setActiveStep((prevStep) => prevStep + 1);
    }
  };

  const handleBack = () => {
    setActiveStep((prevStep) => prevStep - 1);
  };

  const handlePlaceOrder = () => {
    if (!isAuthenticated) {
      setShowLoginAlert(true);
      localStorage.setItem('redirectAfterLogin', '/checkout');
      navigate('/login');
      return;
    }

    // Show success alert
    setOrderSuccess(true);
    
    // Clear cart and navigate after a short delay
    setTimeout(() => {
      dispatch(clearCart());
      navigate('/order-confirmation');
    }, 2000);
  };

  const handleLogin = () => {
    localStorage.setItem('redirectAfterLogin', '/checkout');
    navigate('/login');
  };

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      {showLoginAlert && (
        <Alert 
          severity="info" 
          sx={{ mb: 2 }}
          action={
            <Button 
              color="inherit" 
              size="small"
              onClick={handleLogin}
            >
              Login
            </Button>
          }
        >
          Please login to complete your purchase. You will be redirected back to checkout after login.
        </Alert>
      )}
      
      {orderSuccess && (
        <Alert 
          severity="success" 
          sx={{ 
            mb: 2,
            backgroundColor: '#4caf50',
            color: 'white',
            '& .MuiAlert-icon': {
              color: 'white'
            }
          }}
        >
          Order placed successfully! Redirecting...
        </Alert>
      )}
      <Paper 
        elevation={3} 
        sx={{ 
          p: 4,
          backgroundColor: isDark ? 'background.paper' : 'white',
          borderRadius: 2
        }}
      >
        <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
          {steps.map((label) => (
            <Step key={label}>
              <StepLabel>{label}</StepLabel>
            </Step>
          ))}
        </Stepper>

        <Box sx={{ mt: 2 }}>
          {getStepContent(activeStep)}
        </Box>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 4 }}>
          {activeStep !== 0 && (
            <Button onClick={handleBack} sx={{ mr: 1 }}>
              Back
            </Button>
          )}
          <Button
            variant="contained"
            color="primary"
            onClick={handleNext}
          >
            {activeStep === steps.length - 1 ? 'Place Order' : 'Next'}
          </Button>
        </Box>
      </Paper>
    </Container>
  );
};

export default CheckoutPage;
